func TestScratchPartialConflict(t *testing.T) {
	var v4Occupied, v4Released, v6Occupied, v6Released int

	v4 := &mockCIDRAllocator{
		OnInRange:     func(*net.IPNet) bool { return true },
		OnIsFull:      func() bool { return false },
		OnIsAllocated: func(*net.IPNet) (bool, error) { return false, nil },
		OnOccupy:      func(*net.IPNet) error { v4Occupied++; return nil },
		OnRelease:     func(*net.IPNet) error { v4Released++; return nil },
	}
	// v6 is already allocated elsewhere -> conflict.
	v6 := &mockCIDRAllocator{
		OnInRange:     func(*net.IPNet) bool { return true },
		OnIsFull:      func() bool { return false },
		OnIsAllocated: func(*net.IPNet) (bool, error) { return true, nil },
		OnOccupy:      func(*net.IPNet) error { v6Occupied++; return nil },
		OnRelease:     func(*net.IPNet) error { v6Released++; return nil },
	}

	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{v4},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{v6},
		nodes:               map[string]*nodeCIDRs{},
	}

	got, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.True(t, allocated, "partial conflict should report allocated=true")
	require.Error(t, err)
	require.Contains(t, err.Error(), "already allocated")

	// Only v4 kept, v6 omitted.
	require.Equal(t, mustNewCIDRs("10.10.0.0/24"), got.v4PodCIDRs)
	require.Empty(t, got.v6PodCIDRs)

	// v4 occupied and NOT released; v6 never occupied.
	require.Equal(t, 1, v4Occupied)
	require.Equal(t, 0, v4Released)
	require.Equal(t, 0, v6Occupied)

	// node stored with only v4.
	require.Equal(t, map[string]*nodeCIDRs{
		"node-1": {v4PodCIDRs: mustNewCIDRs("10.10.0.0/24")},
	}, n.nodes)
}

